using System;
using System.Linq;
using System.Collections.Generic;
using System.Text;
public static class ForgeDragonChecks {
 static void Check(bool c,string m){if(!c)throw new Exception(m);}
 static ForgeMvp.Piece Bone()=>new ForgeMvp.Piece{id=4,material=9,data=new ForgeItemData{dragonBone=new ForgeDragonBone(10,new[]{2,4,7})}};
 static ForgeRunContext Context(ForgeMvp.Piece b)=>new ForgeRunContext{PracticeBlade=b,DragonUnlocked=true};
 static Dictionary<int,long> Stocks()=>new Dictionary<int,long>{{9,10},{4,10},{3,10}};
 static ForgeMvp.Evaluation Eval(ForgeMvp.Piece b,string code)=>BlueprintRuntime.Evaluate(code,0,10,"test",1,materialStocks:Stocks(),context:Context(b));
 static void Ok(ForgeMvp.Evaluation e)=>Check(e.error==null,e.error);
 static void Cut(ForgeDragonBone b,int p){Action cancel;var done=b.BeginCut(p,1,out cancel);done();}
 public static string Run(){var log=new StringBuilder();int count=0;Action<string,Action> test=(n,a)=>{a();count++;log.AppendLine("PASS "+n);};
 test("5000 fixed independent valid generations and invalid settings",()=>{for(uint seed=0;seed<5000;seed++){var b=ForgeDragonBone.Create(seed,new ForgeDragonSettings());Check(b.Count>=3&&b.Count<=7,"count");int last=0;for(int i=0;i<b.Count;i++){int p=b.Position(i);Check(p>last&&p<b.Length,"position");last=p;}var clone=b.Clone();Cut(clone,clone.Position(0));Check(b.Cost==0&&b.Position(0)==clone.Position(0),"independent");}try{ForgeDragonBone.Create(1,new ForgeDragonSettings{length=7});throw new Exception("accepted invalid");}catch(ArgumentException){} });
 test("90-95 distinct registration, locked validation",()=>{foreach(int n in Enumerable.Range(90,6))Check(BlueprintAliases.All.Count(a=>a.Symbol==n.ToString())==1,"collision");var b=Bone();var e=BlueprintRuntime.Evaluate("90(Bone)",0,0,"test",1,context:new ForgeRunContext{PracticeBlade=b});Check(e.error!=null,"permission");});
 test("costs 24 and 20 and real duration once",()=>{foreach(var order in new[]{new[]{2,4,7},new[]{4,2,7}}){var b=Bone();var e=Eval(b,string.Join("\n",order.Select(p=>"93(Bone,"+p+")"))+"\nn=91(Bone)\np=92(Bone,0)\nc=95(Bone)\nd=94(Bone,2)");Ok(e);int expected=order[0]==2?24:20;Check(b.data.dragonBone.Cost==expected&&Math.Abs(e.steps.Sum(s=>s.duration)-expected*.1)<.0001,"cost duration");Check((int)e.values["n"]==3&&(int)e.values["p"]==2&&(int)e.values["c"]==expected&&(bool)e.values["d"],"fixed queries");}});
 test("actual queued completion, cancellation, duplicate completion",()=>{var b=Bone();using(var s=BlueprintRuntime.StartSession("93(Bone,4)\nx=1",0,0,context:Context(b))){s.Advance().GetAwaiter().GetResult();var receipt=s.Evaluation.steps.Single();Check(b.data.dragonBone.Cost==0&&!b.data.dragonBone.IsCut(4),"not registered completion");receipt.CompleteWork();receipt.CompleteWork();Check(b.data.dragonBone.Cost==10,"exactly once");}b=Bone();using(var s=BlueprintRuntime.StartSession("93(Bone,4)\nx=1",0,0,context:Context(b))){s.Advance().GetAwaiter().GetResult();var receipt=s.Evaluation.steps.Single();s.Dispose();receipt.CompleteWork();Check(b.data.dragonBone.Cost==0&&!b.data.dragonBone.Pending,"cancelled work");}});
 test("heat ordering 999 1000 1010 and cooling eligibility",()=>{foreach(int temp in new[]{999,1000,1010}){var b=Bone();Ok(Eval(b,"93(Bone,2)\n93(Bone,4)\n93(Bone,7)\n8("+temp+")\n2(Bone)\n4(Bone,0)"));Check(b.data.dragonBone.Qualified==(temp>=1000)&&b.heat==0,"threshold");}foreach(string code in new[]{"8(1000)\n2(Bone)\n93(Bone,2)\n93(Bone,4)\n93(Bone,7)","93(Bone,2)\n8(1000)\n2(Bone)"}){var b=Bone();Ok(Eval(b,code));Check(!b.data.dragonBone.Qualified,"preheat or partial");}var hot=Bone();Ok(Eval(hot,"8(1000)\n2(Bone)\n93(Bone,2)\n93(Bone,4)\n93(Bone,7)\n2(Bone)"));Check(hot.data.dragonBone.Qualified,"new hot heating action");});
 test("heat eligibility waits for receipt completion",()=>{var b=Bone();foreach(int p in new[]{2,4,7})Cut(b.data.dragonBone,p);using(var s=BlueprintRuntime.StartSession("8(1000)\n2(Bone)\nx=1",0,0,materialStocks:Stocks(),context:Context(b))){s.Advance().GetAwaiter().GetResult();s.Advance().GetAwaiter().GetResult();var r=s.Evaluation.steps.Last();Check(!b.data.dragonBone.Qualified,"heat queued");r.CompleteWork();Check(b.data.dragonBone.Qualified,"heat done");}});
 test("errors preserve costs and flags and report line",()=>{foreach(string call in new[]{"90()","90(1)","92(Bone,-1)","92(Bone,3)","93(Bone,0)","93(Bone,10)","93(Bone,3)","93(Bone,True)","94(Bone,3)","95(Bone,1)"}){var b=Bone();var e=Eval(b,"x=0\n"+call);Check(e.error!=null&&e.errorLine==2&&b.data.dragonBone.Cost==0,"atomic "+call);}var cut=Bone();Ok(Eval(cut,"93(Bone,2)"));var duplicate=Eval(cut,"93(Bone,2)");Check(duplicate.error!=null&&cut.data.dragonBone.Cost==10,"duplicate");foreach(bool destroyed in new[]{true,false}){var b=Bone();b.data.destroyed=destroyed;b.data.recovered=!destroyed;Check(Eval(b,"93(Bone,2)").error!=null&&b.data.dragonBone.Cost==0,"dead");}});
 test("actual full guide numeric code transfer and stable pricing",()=>{var e=BlueprintRuntime.Evaluate(ForgeDragonGuide.FullExample,0,10,"test",1,materialStocks:Stocks(),context:new ForgeRunContext{DragonUnlocked=true});Ok(e);var final=e.steps.Last();Check(final.finished&&final.data.handle==9&&final.data.dragonBone.Qualified&&final.data.dragonBone.Used,"transfer");var product=new ForgeProduct("test",final.heat,final.shaped,final.traits,0,1,1,final.data,final.productionSeconds);var first=ForgePricing.Quote(product).SalePrice;for(int i=0;i<20;i++)Check(ForgePricing.Quote(product).SalePrice==first,"stable quote");Check(ForgePricing.Bonuses(product)["용뼈 절단 후 가열"]==200&&ForgePricing.Bonuses(product)["손잡이"]==ForgeBalance.DragonHandleBonus,"existing bonus preserved");var shop=new ForgeShop();int id=shop.Add(product),gold=0;ForgeProduct sold;Check(shop.TrySell(id,ref gold,out sold)&&gold==first,"sale");Check(!shop.TrySell(id,ref gold,out sold)&&gold==first,"sale once");var bad=final.data.Clone();bad.destroyed=true;Check(ForgePricing.Quote(new ForgeProduct("broken",0,true,0,0,0,1,bad)).SalePrice==0,"destroyed");});
 test("practice restores entry state temperature costs eligibility and cancels old work",()=>{var actual=Bone();actual.heat=990;Cut(actual.data.dragonBone,2);using(var practice=new ForgeCoolingPractice(actual,0,true,Stocks())){var s=practice.Start("93(Bone,4)\nx=1");s.Advance().GetAwaiter().GetResult();var old=s.Evaluation.steps.Last();practice.Reset();old.CompleteWork();Check(practice.Blade.heat==990&&practice.Blade.data.dragonBone.Cost==10&&practice.Blade.data.dragonBone.IsCut(2)&&!practice.Blade.data.dragonBone.IsCut(4),"restore start");Check(actual.data.dragonBone.Cost==10&&actual.heat==990,"real unchanged");}});
 test("receipt view matches completed fixed positions and clears consumed target",()=>{var b=Bone();var v=new ForgeCoolingViewState();v.Select(b);Check(v.Blade.material==9,"select");var e=Eval(b,"93(Bone,4)");v.Receipt(e.steps[0]);Check(v.Blade.data.dragonBone.IsCut(4)&&v.BoneLeft==0&&v.BoneRight==10,"display");v.Receipt(new ForgeMvp.Step{finished=true});Check(v.Blade==null,"clear");});
 test("full stepped guide matches immediate evaluation and counts work time only once",()=>{var immediate=BlueprintRuntime.Evaluate(ForgeDragonGuide.FullExample,0,10,"test",1,materialStocks:Stocks(),context:new ForgeRunContext{DragonUnlocked=true});Ok(immediate);using(var session=BlueprintRuntime.StartSession(ForgeDragonGuide.FullExample,0,10,"test",1,materialStocks:Stocks(),context:new ForgeRunContext{DragonUnlocked=true})){int cursor=0,guard=0;while(!session.Completed){Check(++guard<500,"bounded steps");session.Advance().GetAwaiter().GetResult();while(cursor<session.Evaluation.steps.Count)session.Evaluation.steps[cursor++].CompleteWork();}Ok(session.Evaluation);var last=session.Evaluation.steps.Last();Check(last.data.dragonBone.Qualified&&last.data.dragonBone.Used,"stepped bonus transferred");Check(Math.Abs(last.productionSeconds-immediate.steps.Last().productionSeconds)<.0001,"same actual work time");Check(Math.Abs(last.productionSeconds-session.Evaluation.steps.Sum(x=>x.duration))<.0001,"single charge");}});
 test("repeated heating and reset preserve earned qualification without stacking",()=>{var b=Bone();Ok(Eval(b,"93(Bone,2)\n93(Bone,4)\n93(Bone,7)\n8(1000)\n2(Bone)"));for(int i=0;i<4;i++)Ok(Eval(b,"8(1010)\n2(Bone)\n4(Bone,0)"));Check(b.data.dragonBone.Bonus==200&&b.data.dragonBone.Cost==24,"nonstacking");using(var practice=new ForgeCoolingPractice(b,0,true,Stocks())){practice.Reset();Check(practice.Blade.data.dragonBone.Qualified&&practice.Blade.data.dragonBone.Cost==24,"qualified entry restored");}});
 return log+"DragonBone checks: "+count+" passed";
 }
}
